canary_spec.bad_canary_sv:
module canary_test(input logic clkA, clkB, d_i, output logic q_o);
  always_comb begin if (clkA) q_o = d_i ^ clkB; end
endmodule

canary_spec.good_canary_sv:
module canary_test(input logic clkA, clkB, rst_n, d_i, output logic q_o);
  logic src_q, sync_q1, sync_q2;
  always_ff @(posedge clkA or negedge rst_n) if (!rst_n) src_q <= 1'b0; else src_q <= d_i;
  always_ff @(posedge clkB or negedge rst_n) if (!rst_n) {sync_q2, sync_q1} <= 2'b00; else {sync_q2, sync_q1} <= {sync_q1, src_q};
  assign q_o = sync_q2;
endmodule

canary_spec.bad_canary_sv:
module canary_test(input logic clk_i, input logic [3:0] ptr_i, output logic [3:0] ptr_o);
  always_ff @(posedge clk_i) ptr_o = ptr_i;
endmodule

canary_spec.good_canary_sv:
module canary_test(input logic clk_i, rst_ni, input logic [3:0] ptr_i, output logic [3:0] ptr_o);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) ptr_o <= 4'd0;
    else         ptr_o <= (ptr_i >> 1) ^ ptr_i;
  end
endmodule

golden_template:
// [GOLDEN PATTERN] Asynchronous Assert, Synchronous Deassert Reset Bridge
always_ff @(posedge clk_i or negedge ext_rst_ni) begin
  if (!ext_rst_ni) {rst_sync_q2, rst_sync_q1} <= 2'b00;
  else             {rst_sync_q2, rst_sync_q1} <= {rst_sync_q1, 1'b1};
end
assign sys_rst_no = rst_sync_q2;

canary_spec.bad_canary_sv:
module canary_test(input logic clk_i, ext_rst_ni, output logic sys_rst_no);
  always_comb begin if (!ext_rst_ni) sys_rst_no = clk_i; end
endmodule

canary_spec.good_canary_sv:
module canary_test(input logic clk_i, ext_rst_ni, output logic sys_rst_no);
  logic rst_q1, rst_q2;
  always_ff @(posedge clk_i or negedge ext_rst_ni) begin
    if (!ext_rst_ni) {rst_q2, rst_q1} <= 2'b00;
    else             {rst_q2, rst_q1} <= {rst_q1, 1'b1};
  end
  assign sys_rst_no = rst_q2;
endmodule
